<?php
use App\Http\Controllers\AllocationController;
use App\Http\Controllers\AllocationA6Controller;
use App\Http\Controllers\AllocationDispositionController;
use App\Http\Middleware\ConfigureExaminationConnection;
use App\Http\Middleware\EnsureExaminationSelected;
use Illuminate\Support\Facades\Route;

Route::middleware([EnsureExaminationSelected::class, ConfigureExaminationConnection::class])->prefix('allocation')->name('allocation.')->group(function(){
    Route::get('/',[AllocationController::class,'index'])->name('index');
    Route::post('/settings/finalize',[AllocationController::class,'finalizeSettings'])->name('settings.finalize');
    Route::post('/input-freeze/freeze',[AllocationController::class,'freezeInputs'])->name('input-freeze.freeze');
    Route::get('/input-freeze/status',[AllocationController::class,'inputFreezeStatus'])->name('input-freeze.status');
    Route::get('/input-freeze/{freeze}',[AllocationController::class,'showInputFreeze'])->name('input-freeze.show');
    Route::get('/input-freeze/{freeze}/cadre/{circularEntry}/queue',[AllocationController::class,'showCadreQueue'])->name('input-freeze.cadre-queue');
    Route::post('/phase-one/start',[AllocationController::class,'startPhaseOne'])->name('phase-one.start');
    Route::get('/phase-one/status',[AllocationController::class,'phaseOneStatus'])->name('phase-one.status');
    Route::get('/runs/{run}',[AllocationController::class,'showRun'])->name('runs.show');
    Route::get('/runs/{run}/candidates',[AllocationController::class,'showRunCandidates'])->name('runs.candidates');
    Route::get('/runs/{run}/cadre/{circularEntry}',[AllocationController::class,'showRunCadreResults'])->name('runs.cadre-results');
    Route::post('/runs/{run}/a4/start',[AllocationController::class,'startA4'])->name('a4.start');
    Route::get('/a4/runs/{a4Run}/status',[AllocationController::class,'a4Status'])->name('a4.status');
    Route::get('/a4/runs/{a4Run}/processing',[AllocationController::class,'showA4Processing'])->name('a4.processing');
    Route::get('/a4/runs/{a4Run}',[AllocationController::class,'showA4'])->name('a4.show');
    Route::get('/a4/runs/{a4Run}/candidates',[AllocationController::class,'showA4Candidates'])->name('a4.candidates');
    Route::get('/a4/runs/{a4Run}/cadre/{circularEntry}',[AllocationController::class,'showA4CadreResults'])->name('a4.cadre-results');
    Route::post('/a5/start',[AllocationController::class,'startA5'])->name('a5.start');
    Route::get('/a5/runs/{a5Run}/status',[AllocationController::class,'a5Status'])->name('a5.status');
    Route::get('/a5/runs/{a5Run}/processing',[AllocationController::class,'showA5Processing'])->name('a5.processing');
    Route::get('/a5/runs/{a5Run}',[AllocationController::class,'showA5'])->name('a5.show');
    Route::get('/a5/runs/{a5Run}/candidates',[AllocationController::class,'showA5Candidates'])->name('a5.candidates');
    Route::get('/a5/runs/{a5Run}/cadre/{circularEntry}',[AllocationController::class,'showA5CadreResults'])->name('a5.cadre-results');
    Route::post('/a5/runs/{a5Run}/finalize',[AllocationController::class,'finalizeA5'])->name('a5.finalize');
    Route::get('/a5-5',[AllocationDispositionController::class,'index'])->name('disposition.index');
    Route::get('/a5-5/candidates/{registrationId}',[AllocationDispositionController::class,'show'])->name('disposition.show');
    Route::put('/a5-5/candidates/{registrationId}',[AllocationDispositionController::class,'update'])->name('disposition.update');
    Route::get('/a6',[AllocationA6Controller::class,'index'])->name('a6.index');
    Route::get('/a6/candidates',[AllocationA6Controller::class,'candidates'])->name('a6.candidates');
    Route::get('/a6/candidates/{reg}',[AllocationA6Controller::class,'candidate'])->name('a6.candidate');
    Route::get('/a6/cadres',[AllocationA6Controller::class,'cadres'])->name('a6.cadres');
    Route::get('/a6/cadres/{cadreCode}',[AllocationA6Controller::class,'cadre'])->name('a6.cadre');
    Route::get('/a6/summary',[AllocationA6Controller::class,'summary'])->name('a6.summary');
    Route::post('/a6/summary/export',[AllocationA6Controller::class,'startSummaryExport'])->name('a6.summary.export');
    Route::get('/a6/summary/short',[AllocationA6Controller::class,'shortSummary'])->name('a6.summary.short');
    Route::post('/a6/summary/short/export',[AllocationA6Controller::class,'startShortSummaryExport'])->name('a6.summary.short.export');
    Route::post('/a6/exports/txt',[AllocationA6Controller::class,'startTxt'])->name('a6.exports.txt');
    Route::post('/a6/exports/xlsx',[AllocationA6Controller::class,'startXlsx'])->name('a6.exports.xlsx');
    Route::get('/a6/exports/excel-builder',[AllocationA6Controller::class,'excelBuilder'])->name('a6.exports.excel-builder');
